head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.clickId;
scwin.gIsurCd;
scwin.clickBzProcsNo;
scwin.clickListBzDtlTpCd;
scwin.clickListInvstgBzTpCd;
scwin.clickListProcsStatCd;
scwin.clickListInvstgAttachFileTpCd;
scwin.vScrenID = "ULDSTF07242.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    if (scwin.dateCheck() == false) {
        return;
    }
    var vKosdaq_Bbs_Tp_Cd_1 = '';
    var vKosdaq_Bbs_Tp_Cd_2 = '';
    if ($c.stf.getObjectValue(cmb_Kosdaq_Bbs_Tp_Cd) == '12') {
        vKosdaq_Bbs_Tp_Cd_1 = '170';
    } else {
        vKosdaq_Bbs_Tp_Cd_1 = $c.stf.getObjectValue(cmb_Kosdaq_Bbs_Tp_Cd);
    }
    if ($c.stf.getObjectValue(cmb_Kosdaq_Bbs_Tp_Cd) == '180') {
        vKosdaq_Bbs_Tp_Cd_2 = '13';
    } else {
        vKosdaq_Bbs_Tp_Cd_2 = $c.stf.getObjectValue(cmb_Kosdaq_Bbs_Tp_Cd);
    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=FORNCOM_ANLRPT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstinvstg.nwlist.forncom.anlrpt.list" + "&{P}param01=" + $c.stf.getObjectValue(txb_isur_cd) + // 	회사명
        "&{P}param02=" + $c.stf.getObjectValue(txb_isur_cd) + // 	회사명
        "&{P}param03=" + $c.stf.getObjectValue(rdo_MKT_ID) + // 	시장구분
        "&{P}param04=" + $c.stf.getObjectValue(rdo_MKT_ID) + // 	시장구분
        "&{P}param05=" + vKosdaq_Bbs_Tp_Cd_1 + // 	보고서구분
        "&{P}param06=" + vKosdaq_Bbs_Tp_Cd_1 + // 	보고서구분
        "&{P}param07=" + $c.stf.getObjectValue(edt_SDate) + //	조회시작일자
        "&{P}param08=" + $c.stf.getObjectValue(edt_EDate) + //	조회종료일자
        "&{P}param09=" + $c.stf.getObjectValue(txb_Title) + // 	제목
        "&{P}param10=" + $c.stf.getObjectValue(txb_Title) + //	제목
        "&{P}param11=" + $c.stf.getObjectValue(tbx_wrt_inst_nm) + //	작성기관
        "&{P}param12=" + $c.stf.getObjectValue(tbx_wrt_inst_nm) + //	작성기관
        "&{P}param13=" + $c.stf.getObjectValue(rdo_GUBUN) + //	업로드여부
        "&{P}param14=" + $c.stf.getObjectValue(rdo_GUBUN) + //	업로드여부
        "&{P}param15=" + $c.stf.getObjectValue(txb_isur_cd) + // 	회사명
        "&{P}param16=" + $c.stf.getObjectValue(txb_isur_cd) + // 	회사명
        "&{P}param17=" + $c.stf.getObjectValue(rdo_MKT_ID) + // 	시장구분
        "&{P}param18=" + $c.stf.getObjectValue(rdo_MKT_ID) + // 	시장구분
        "&{P}param19=" + vKosdaq_Bbs_Tp_Cd_2 + // 	보고서구분
        "&{P}param20=" + vKosdaq_Bbs_Tp_Cd_2 + // 	보고서구분
        "&{P}param21=" + $c.stf.getObjectValue(edt_SDate) + //	조회시작일자
        "&{P}param22=" + $c.stf.getObjectValue(edt_EDate) + //	조회종료일자
        "&{P}param23=" + $c.stf.getObjectValue(txb_Title) + // 	제목
        "&{P}param24=" + $c.stf.getObjectValue(txb_Title) + //	제목
        "&{P}param25=" + $c.stf.getObjectValue(tbx_wrt_inst_nm) + //	작성기관
        "&{P}param26=" + $c.stf.getObjectValue(tbx_wrt_inst_nm) + //	작성기관
        "&{P}param27=" + $c.stf.getObjectValue(rdo_GUBUN) + //	업로드여부
        "&{P}param28=" + $c.stf.getObjectValue(rdo_GUBUN); //	업로드여부

    dts_irCeoList.DataID = encodeURI(url);
    dts_irCeoList.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_setId = function(obj) {
    if (scwin.clickId != "input") {
        scwin.clickId = dts_irCeoList.getCellData(eval(obj), "BZ_PROCS_NO");
    }
};
scwin.fn_getId = function() {
    return scwin.clickId;
};
scwin.fn_setParam = function(obj) {
    scwin.clickBzProcsNo = dts_irCeoList.getCellData(eval(obj), 'BZ_PROCS_NO');
    scwin.clickListBzDtlTpCd = dts_irCeoList.getCellData(eval(obj), 'LIST_BZ_DTL_TP_CD');
    scwin.clickListInvstgBzTpCd = dts_irCeoList.getCellData(eval(obj), 'LIST_INVSTG_BZ_TP_CD');
    scwin.clickListProcsStatCd = dts_irCeoList.getCellData(eval(obj), 'LIST_PROCS_STAT_CD');
    scwin.clickListInvstgAttachFileTpCd = dts_irCeoList.getCellData(eval(obj), 'LIST_INVSTG_ATTACH_FILE_TP_CD');
};
scwin.dateCheck = function() {
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.]\n\n다시 입력해주세요.");
        edt_SDate.setValue($c.ut.cGetToday("yyyymmdd"));
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
        return false;
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 3)); // 3달전 날짜	
    edt_EDate.setValue(vCurDate);
    if (js_market == '1' || js_market == '2' || js_market == '6') {
        $c.stf.setObjectValue(rdo_MKT_ID, js_market);
        rdo_MKT_ID.setDisabled(true);
    } else {
        $c.stf.setObjectValue(rdo_MKT_ID, '9');
        rdo_MKT_ID.setDisabled(false);
    }
    scwin.fn_list_sync();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    if (row > 0) {
        scwin.gIsurCd = dts_irCeoList.getCellData(row, "ISUR_CD");
        if (colid == 'CONTN_TITLE') {
            if (dts_irCeoList.getCellData(dts_irCeoList.getRowPosition(), "GUBUN") == "1") {
                // 업로드(제출)	
                scwin.fn_setParam(row);
                await $c.frame.CreateDialogFrame("gform", "/lstinvstg/ULDSTF07244.gfm", "신규상장 기업분석보고서/사업모델 평가보고서 및 기업 계속성 보고서 상세", 200, 100, 1010, 300, "window");
                scwin.fn_list_sync();
            } else if (dts_irCeoList.getCellData(dts_irCeoList.getRowPosition(), "GUBUN") == "2") {
                // 접수(처리)
                scwin.fn_setId(row);
                await $c.frame.CreateDialogFrame("gform", "/lstinvstg/ULDSTF07245.gfm", "신규상장 기업분석보고서/사업모델 평가보고서 및 기업 계속성 보고서 수정", 200, 100, 750, 590, "window");
                scwin.fn_list_sync();
            }
        } else if (colid == "COM_NM") {
            $c.stf.fn_PopupCorpInfo();
        } else if (colid == 'LIST_PROCS_STAT_NM') {
            if (dts_irCeoList.getCellData(dts_irCeoList.getRowPosition(), "GUBUN") == "1") {
                // 업로드(제출)
                if ("34" == dts_irCeoList.getCellData(row, 'LIST_PROCS_STAT_CD')) {
                    scwin.fn_setParam(row);
                    //수정요청 리스트 팝업창
                    await $c.frame.CreateDialogFrame("ULDSTF07243.gfm", "/lstinvstg/ULDSTF07243.gfm", "신규상장 기업분석보고서/사업모델 평가보고서 및 기업 계속성 보고서 수정요청 리스트", 50, 50, 940, 280, "window");
                }
            } else {
                // 접수(처리)
                $c.win.alert("해당건은  업로드(제출)인 경우에 한하여 승인여부가 가능합니다.");
                return;
            }
        }
    }
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.txb_isur_cd_onblur = function() {
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch_IR(txb_isur_cd, txb_com_abbrv);
};
scwin.btn_Input_onclick = async function() {
    scwin.clickId = "input";
    await $c.frame.CreateDialogFrame("gform", "/lstinvstg/ULDSTF07245.gfm", "신규상장 기업분석보고서/사업모델 평가보고서 및 기업 계속성 보고서 등록", 200, 100, 745, 590, "window");
    scwin.clickId = "";
    scwin.fn_list_sync();
};
scwin.icn_SCal_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.icn_ECal_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.dts_irCeoList_OnFail = function() {
    $c.stf.alert_error(dts_irCeoList);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_irCeoList_OnLoadError = function() {
    $c.stf.alert_error(dts_irCeoList);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_irCeoList_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    if (rowcount <= 0) {
        dts_irCeoList.removeAll();
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "신규상장 기업분석/사업모델평가및기업계속성 보고서 관리", "", "2");
};
scwin.txb_Title_onkeydown = function() {
    if (window.event.keyCode == "13") {
        scwin.fn_list_sync();
    }
};
scwin.tbx_wrt_inst_nm_onkeydown = function() {
    if (window.event.keyCode == "13") {
        scwin.fn_list_sync();
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
